SELECT s1."c0" AS "d", s1."c1" AS "next_day", s1."c2" AS "later" FROM (SELECT s2."c7" AS "c0", s2."c8" AS "c1", s2."c9" AS "c2" FROM (SELECT s3."c0" AS "c0", s3."c1" AS "c1", s3."c2" AS "c2", s3."c3" AS "c3", s3."c4" AS "c4", s3."c5" AS "c5", s3."c6" AS "c6", s3."c0" AS "c7", (CASE WHEN (DATEDIFF(DAY, CAST('1970-01-01' AS DATE), s3."c0") NOT BETWEEN -96465292 AND 95026236 OR DATEDIFF(DAY, CAST('1970-01-01' AS DATE), DATEADD(DAY, 1, (CASE WHEN DATEDIFF(DAY, CAST('1970-01-01' AS DATE), s3."c0") BETWEEN -96465292 AND 95026236 THEN s3."c0" END))) NOT BETWEEN -96465292 AND 95026236) THEN CAST('sverify: date + days outside the dates DataFusion computes: ' || TO_VARCHAR(s3."c0") AS DATE) ELSE DATEADD(DAY, 1, (CASE WHEN DATEDIFF(DAY, CAST('1970-01-01' AS DATE), s3."c0") BETWEEN -96465292 AND 95026236 THEN s3."c0" END)) END) AS "c8", (s3."c0" < (CASE WHEN (DATEDIFF(DAY, CAST('1970-01-01' AS DATE), s3."c0") NOT BETWEEN -96465292 AND 95026236 OR DATEDIFF(DAY, CAST('1970-01-01' AS DATE), DATEADD(DAY, 7, (CASE WHEN DATEDIFF(DAY, CAST('1970-01-01' AS DATE), s3."c0") BETWEEN -96465292 AND 95026236 THEN s3."c0" END))) NOT BETWEEN -96465292 AND 95026236) THEN CAST('sverify: date + days outside the dates DataFusion computes: ' || TO_VARCHAR(s3."c0") AS DATE) ELSE DATEADD(DAY, 7, (CASE WHEN DATEDIFF(DAY, CAST('1970-01-01' AS DATE), s3."c0") BETWEEN -96465292 AND 95026236 THEN s3."c0" END)) END)) AS "c9" FROM (SELECT "d" AS "c0", "d2" AS "c1", "ts" AS "c2", "x" AS "c3", "s" AS "c4", "ok" AS "c5", ("v" + CAST('0.0' AS FLOAT)) AS "c6" FROM "events") AS s3) AS s2) AS s1
